"use strict";
const v8 = require("node:v8");
const vm = require("node:vm");
v8.setFlagsFromString("--expose-gc");
const gc = vm.runInNewContext("gc");

// Remembers a native object weakly. (A WeakRef would keep its target until
// the current job ends, which hides a collected representative.)
const seen = new WeakMap();
exports.remember = (o) => {
  seen.set(o, "remembered");
};
exports.collect = () => {
  for (let i = 0; i < 3; i++) gc();
};
exports.check = (o) => seen.get(o) ?? "forgotten";
